const{test}=require('node:test');const assert=require('node:assert/strict');const vm=require('node:vm');const fs=require('node:fs');
function game(expanded=false,reactions=false){const es=new Map;const timers=[];function el(key){if(!es.has(key))es.set(key,{textContent:'',innerHTML:'',value:'',dataset:{},style:{setProperty(){}},classList:{add(){},remove(){},toggle(){},contains(){return false}},addEventListener(){},removeEventListener(){},querySelectorAll(){return[]},setAttribute(){},removeAttribute(){},showModal(){this.open=true},show(){this.open=true},close(){this.open=false},getBoundingClientRect(){return{left:0,top:0,width:150,height:210}},isConnected:true});return es.get(key)}const c=vm.createContext({console,queuedTimers:timers,document:{querySelector:el,querySelectorAll:()=>[],documentElement:el('html'),body:el('body'),addEventListener(){}},window:{innerWidth:1600,innerHeight:900,addEventListener(){},scrollTo(){}},requestAnimationFrame(){},setTimeout(fn){timers.push(fn);return timers.length},clearTimeout(){},AbortSignal,localStorage:{getItem(){return null},setItem(){}}});for(const f of ['cards.js','sounds.js','game.js','rules.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);if(expanded)for(const f of ['expansion.js','expedition-rewards.js','enemy-spells.js','enemy-counters.js','waves.js','dice.js','dice-cards.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);if(reactions)vm.runInContext(fs.readFileSync('reaction-checks.js','utf8'),c);const run=code=>vm.runInContext(code,c);run(`state.soundOn=false;renderBattle=()=>{};showScreen=id=>state.screen=id;globalThis.card=name=>BUNDLED_CARDS.find(card=>card.name===name);state.pool=playableCards(BUNDLED_CARDS);state.deck=Array.from({length:30},()=>card('Grizzly Bears'));beginBattle(1);state.battle.floatingMana=30;syncMana(state.battle);state.battle.enemyCreatures.forEach(enemy=>{enemy.health=50;enemy.maxHealth=50;enemy.hexproof=false;enemy.flying=false;enemy.lifelink=false;enemy.power=1;enemy.summoningSick=false;enemy.summonedTurn=0});state.battle.hand=[];state.battle.creatures=[];globalThis.hand=(...names)=>state.battle.hand=names.map(card);globalThis.ally=(name='Grizzly Bears',id='a')=>{let c=card(name);let u={id,card:c,owner:'player',...parseStats(c),...creatureKeywords(c),summonedTurn:0,summoningSick:true,tapped:false,willAttack:false};state.battle.creatures.push(u);return u};globalThis.pick=key=>{selectRuleChoice(key);confirmRuleChoice()};`);return run;}
for(const name of ['Duress','Reverberate'])test(`${name} is banned with a reason`,()=>{const r=game();assert.equal(r(`rulesAudit(card(${JSON.stringify(name)})).playable`),false);assert.ok(r(`rulesAudit(card(${JSON.stringify(name)})).reason.length`)>25)});
test('unsupported text never becomes substitute damage; keyword-only creatures are allowed',()=>{const r=game();assert.equal(r(`rulesAudit({name:'unknown',type_line:'Instant',oracle_text:'Take an extra turn.',keywords:[]}).playable`),false);assert.equal(r(`cardEffects({name:'unknown',type_line:'Instant',oracle_text:'Take an extra turn.',keywords:[]}).length`),0);assert.equal(r(`rulesAudit(card('Fencing Ace')).playable`),true)});
test('packs and all three shop offers exclude banned cards',()=>{const r=game();r(`state.pool=BUNDLED_CARDS;globalThis.packs=makeStarterPacks();state.node=2;state.coins=100;showShop()`);assert.equal(r('packs.length'),6);assert.equal(r('packs.every(pack=>pack.length===7&&pack.every(c=>rulesAudit(c).playable))'),true);assert.equal(r('state.shop.offers.length'),3);assert.equal(r('state.shop.offers.every(offer=>rulesAudit(offer.card).playable)'),true)});
test('discard choices exclude the casting card and cancel leaves all costs untouched',()=>{const r=game();r(`hand('Thrill of Possibility','Divination');globalThis.before=state.battle.mana;playCard(0)`);assert.equal(r('choiceOptions(state.battle.choice).length'),1);assert.equal(r('state.battle.mana'),r('before'));r('cancelRuleChoice()');assert.equal(r('state.battle.hand.length'),2);assert.equal(r('state.battle.graveyard.length'),0);assert.equal(r('state.battle.mana'),r('before'))});
test('discard is paid once before drawing and mana includes coloured symbols generically',()=>{const r=game();r(`hand('Thrill of Possibility','Divination');globalThis.before=state.battle.mana;playCard(0);pick('1')`);assert.equal(r('state.battle.hand.length'),2);assert.equal(r('state.battle.graveyard.map(c=>c.name).sort().join()'),'Divination,Thrill of Possibility');assert.equal(r('before-state.battle.mana'),2)});
test('two-card discard cannot be confirmed with only one card selected',()=>{const r=game();r(`hand('Cathartic Reunion','Divination','Revitalize');playCard(0);selectRuleChoice('1');confirmRuleChoice()`);assert.equal(r('state.battle.choice.selected.size'),1);assert.equal(r('state.battle.hand.length'),3);r(`selectRuleChoice('2');confirmRuleChoice()`);assert.equal(r('state.battle.hand.length'),3);assert.equal(r('state.battle.graveyard.length'),3)});
test('additional discard/sacrifice costs must exist before casting',()=>{const r=game();r(`hand('Thrill of Possibility')`);assert.equal(r('canCastNow(state.battle.hand[0])'),false);r(`hand('Village Rites')`);assert.equal(r('canCastNow(state.battle.hand[0])'),false)});
test('sacrifice chooses its victim, kills auras, detaches equipment and triggers morbid',()=>{const r=game();r(`ally();ally('Serra Angel','b');state.battle.permanents=[{id:'s',card:card('Short Sword'),attachedTo:'a'},{id:'h',card:card('Holy Strength'),attachedTo:'a'}];hand('Village Rites');playCard(0);pick('a')`);assert.equal(r('state.battle.creatures.length'),1);assert.equal(r('state.battle.creatures[0].id'),'b');assert.equal(r('state.battle.permanents.length'),1);assert.equal(r('state.battle.permanents[0].attachedTo'),null);assert.equal(r('state.battle.creatureDiedThisTurn'),true);assert.equal(r('state.battle.hand.length'),2)});
test('Rancor returns to hand on sacrifice',()=>{const r=game();r(`ally();state.battle.permanents=[{id:'r',card:card('Rancor'),attachedTo:'a'}];hand('Village Rites');playCard(0);pick('a')`);assert.equal(r(`state.battle.hand.some(c=>c.name==='Rancor')`),true)});
test('Raise Dead chooses only creature cards and returns one without casting it',()=>{const r=game();r(`state.battle.graveyard=[card('Divination'),card('Serra Angel')];hand('Raise Dead');playCard(0)`);assert.equal(r('choiceOptions(state.battle.choice).length'),1);r(`pick('grave:1')`);assert.equal(r('state.battle.hand[0].name'),'Serra Angel');assert.equal(r('state.battle.creatures.length'),0);assert.equal(r(`state.battle.graveyard.some(c=>c.name==='Raise Dead')`),true)});
test('creature pumps choose a target and never become shield without creatures',()=>{const r=game();r(`ally();ally('Serra Angel','b');hand('Giant Growth');playCard(0);pick('player:b')`);assert.equal(r('state.battle.creatures[0].power'),2);assert.equal(r('state.battle.creatures[1].power'),7);r('expireTurnEffects(state.battle)');assert.equal(r('state.battle.creatures[1].power'),4)});
test('Snakeskin Veil restricts its target to your creatures and hexproof expires',()=>{const r=game();r(`ally();hand('Snakeskin Veil');playCard(0)`);assert.equal(r('choiceOptions(state.battle.choice).every(o=>o.unit.owner===\'player\')'),true);r(`pick('player:a')`);assert.equal(r('state.battle.creatures[0].counterPower'),1);assert.equal(r(`hasCreatureKeyword(state.battle.creatures[0],'hexproof')`),true);r('expireTurnEffects(state.battle)');assert.equal(r(`hasCreatureKeyword(state.battle.creatures[0],'hexproof')`),false);assert.equal(r('state.battle.creatures[0].power'),3)});
test('Hunger uses one counter normally and three after a creature death',()=>{for(const died of [false,true]){const r=game();r(`ally();state.battle.creatureDiedThisTurn=${died};hand('Hunger of the Howlpack');playCard(0);pick('player:a')`);assert.equal(r('state.battle.creatures[0].counterPower'),died?3:1)}});
test('Invigorating Surge doubles counters, never equipment or temporary bonuses',()=>{const r=game();r(`ally();let u=state.battle.creatures[0];u.counterPower=2;u.counterToughness=2;u.power+=2;u.toughness+=2;state.battle.permanents=[{id:'s',card:card('Short Sword'),attachedTo:'a'}];refreshPermanentEffects();hand('Invigorating Surge');playCard(0);pick('player:a')`);assert.equal(r('state.battle.creatures[0].counterPower'),6);assert.equal(r('state.battle.creatures[0].power'),9)});
test('Doublecast copies the next draw spell once, with one mana payment and one physical card',()=>{const r=game();r(`hand('Doublecast','Divination');playCard(0);globalThis.before=state.battle.mana;playCard(0)`);assert.equal(r('state.battle.hand.length'),4);assert.equal(r('before-state.battle.mana'),3);assert.equal(r('state.battle.graveyard.length'),2);assert.equal(r('state.battle.copyNextSpell'),0)});
test('copying a sacrifice spell does not sacrifice two creatures',()=>{const r=game();r(`ally();ally('Serra Angel','b');hand('Doublecast','Village Rites');playCard(0);playCard(0);pick('a')`);assert.equal(r('state.battle.creatures.length'),1);assert.equal(r('state.battle.hand.length'),4)});
test('copying a discard spell pays additional costs once',()=>{const r=game();r(`hand('Doublecast','Thrill of Possibility','Revitalize');playCard(0);playCard(0);pick('1')`);assert.equal(r('state.battle.hand.length'),4);assert.equal(r('state.battle.graveyard.length'),3)});
test('Doublecast expires at turn end and is not consumed by creatures or auras',()=>{const r=game();r(`ally();hand('Doublecast','Holy Strength');playCard(0);playCard(0);pick('player:a')`);assert.equal(r('state.battle.copyNextSpell'),1);r('expireTurnEffects(state.battle)');assert.equal(r('state.battle.copyNextSpell'),0)});
test('a copied removal spell fizzles on its removed target rather than auto-retargeting',()=>{const r=game();r(`hand('Doublecast','Murder');playCard(0);playCard(0);pick('enemy:'+state.battle.enemyCreatures[0].id)`);assert.equal(r('state.battle.enemyCreatures.length'),1)});
test('Clone copies printed characteristics and abilities but not counters, tap or equipment',()=>{const r=game();r(`ally('Serra Angel');state.battle.creatures[0].counterPower=4;state.battle.creatures[0].power=8;state.battle.creatures[0].tapped=true;hand('Clone');playCard(0,'player');pick('player:a')`);assert.equal(r('state.battle.creatures[1].power'),4);assert.equal(r('state.battle.creatures[1].tapped'),false);assert.equal(r(`hasCreatureKeyword(state.battle.creatures[1],'vigilance')`),true);r(`state.battle.creatures[1].damage=99;state.battle.creatures=removeDeadCreatures(state.battle.creatures,'player')`);assert.equal(r('state.battle.graveyard.at(-1).name'),'Clone')});
test('enemy hexproof removes opposing targets while still allowing your own hexproof creature',()=>{const r=game();r(`ally();state.battle.creatures[0].hexproof=true;state.battle.enemyCreatures.forEach(e=>e.hexproof=true)`);assert.equal(r(`ruleTargetOptions('creature').length`),1);assert.equal(r(`ruleTargetOptions('creature')[0].key`),'player:a')});
test('Auras can target an enemy and their physical stats apply exactly once',()=>{const r=game();r(`hand('Holy Strength');globalThis.e=state.battle.enemyCreatures[0];globalThis.p=e.power;globalThis.h=e.health;playCard(0);pick('enemy:'+e.id);refreshPermanentEffects();refreshPermanentEffects()`);assert.equal(r('e.power-p'),1);assert.equal(r('e.health-h'),2);r(`state.battle.resolvingSpellTarget={side:'enemy',id:e.id};removeSpellTarget('destroy')`);assert.equal(r('state.battle.permanents.length'),0);assert.equal(r(`state.battle.graveyard.some(c=>c.name==='Holy Strength')`),true)});
test('damage choices include your own life and an explicitly chosen ally',()=>{const r=game();r(`ally();hand('Shock');playCard(0);pick('player:a')`);assert.equal(r('state.battle.creatures.length'),0);const q=game();q(`hand('Shock');globalThis.life=state.playerHealth;playCard(0);pick('life:player')`);assert.equal(q('life-state.playerHealth'),2)});
test('equip pays its printed cost each time and cannot equip outside main',()=>{const r=game();r(`ally();ally('Serra Angel','b');hand('Trusty Machete');playCard(0);globalThis.before=state.battle.mana;state.battle.pendingAttachment={permanentId:state.battle.permanents[0].id};selectAttachmentTarget('a')`);assert.equal(r('before-state.battle.mana'),2);r(`state.battle.pendingAttachment={permanentId:state.battle.permanents[0].id};state.battle.phase='blocks';selectAttachmentTarget('b')`);assert.equal(r('state.battle.permanents[0].attachedTo'),'a')});
test('first strike, flying, vigilance and multi-block stay independent',()=>{const r=game();assert.equal(r('canBlockCreature({reach:true},{flying:true})'),true);assert.equal(r('canBlockCreature({},{flying:true})'),false);assert.equal(r('dealsInCombatStep({firstStrike:true},false)'),false);assert.equal(r('dealsInCombatStep({doubleStrike:true},false)'),true);r(`ally();ally('Serra Angel','b');state.battle.phase='blocks';let e=state.battle.enemyCreatures[0];e.pattern=['attack'];state.battle.turn=2;assignBlocker(e.id,'a');assignBlocker(e.id,'b')`);assert.equal(r('blockerIds(state.battle,state.battle.enemyCreatures[0].id).length'),2)});
test('an empty-library draw loses rather than recycling discarded cards',()=>{const r=game();r(`state.battle.deck=[];state.battle.graveyard=[card('Grizzly Bears')];hand('Divination');playCard(0)`);assert.equal(r('state.battle.phase'),'complete');assert.equal(r('state.screen'),'end-screen')});
test('118 bundled Scryfall cards have unique IDs and original local JPEGs',()=>{const r=game();const cards=JSON.parse(r('JSON.stringify(BUNDLED_CARDS)'));assert.equal(cards.length,118);assert.equal(new Set(cards.map(c=>c.id)).size,118);for(const card of cards){assert.equal(card.verified,true);assert.equal(fs.readFileSync(card.image).readUInt16BE(0),0xffd8)}});

test('temporary enemy toughness preserves marked damage when the bonus expires',()=>{const r=game();r(`hand('Giant Growth');globalThis.e=state.battle.enemyCreatures[0];playCard(0);pick('enemy:'+e.id);e.health-=2;expireTurnEffects(state.battle)`);assert.equal(r('e.health'),48);assert.equal(r('e.maxHealth'),50)});

test('expanded catalog contains reviewed draw, vigilance, Ward and exile cards, while player Mill is banned',()=>{const r=game(true);assert.equal(r('BUNDLED_CARDS.length'),118);assert.equal(r('playableCards(BUNDLED_CARDS).length'),115);for(const n of ['Brainstorm','Opt','Preordain','Serum Visions','Veteran Cavalier','Serra Sphinx','Tomakul Honor Guard','Su-Chi Cave Guard','Final Judgment','Scour from Existence'])assert.equal(r(`rulesAudit(card(${JSON.stringify(n)})).playable`),true);assert.equal(r(`rulesAudit({name:'Mill fixture',type_line:'Instant',oracle_text:'Target player mills two cards. Draw a card.'}).playable`),false);assert.equal(r(`playableCards(BUNDLED_CARDS).some(c=>c.name==='Booster Tutor')`),false)});
test('Brainstorm draws three, returns two chosen cards in order and does not discard',()=>{const r=game(true);r(`state.battle.deck=[card('Shock'),card('Divination'),card('Serra Angel')];hand('Brainstorm','Giant Growth');playCard(0)`);assert.equal(r('state.battle.hand.length'),4);assert.equal(r('state.battle.libraryOrder.count'),2);r(`pickLibraryOrder27(0);pickLibraryOrder27(2);finishLibraryOrder27()`);assert.equal(r('state.battle.hand.length'),2);assert.equal(r('state.battle.deck.pop().name'),'Giant Growth');assert.equal(r('state.battle.deck.pop().name'),'Divination');assert.equal(r('state.battle.graveyard.length'),1);assert.equal(r('state.battle.resolutionTask'),null)});
test('Brainstorm cannot finish its mandatory return with only one card chosen',()=>{const r=game(true);r(`hand('Brainstorm');playCard(0);pickLibraryOrder27(0);finishLibraryOrder27()`);assert.equal(r('state.battle.libraryOrder.selected.length'),1);assert.notEqual(r('state.battle.resolutionTask'),null)});
test('Doublecast Brainstorm finishes each draw/return sequence before the next copy',()=>{const r=game(true);r(`hand('Doublecast','Brainstorm');playCard(0);playCard(0);pickLibraryOrder27(0);pickLibraryOrder27(1);finishLibraryOrder27()`);assert.notEqual(r('state.battle.libraryOrder'),null);r(`pickLibraryOrder27(0);pickLibraryOrder27(1);finishLibraryOrder27()`);assert.equal(r('state.battle.libraryOrder'),null);assert.equal(r('state.battle.resolutionTask'),null);assert.equal(r('state.battle.graveyard.length'),2)});
test('Preordain scries before drawing while Serum Visions draws before scrying',()=>{const r=game(true);r(`state.battle.deck=[card('Shock'),card('Divination'),card('Serra Angel')];hand('Preordain');playCard(0);state.battle.scry.cards[0].bottom=true;finishScry()`);assert.equal(r('state.battle.hand[0].name'),'Divination');assert.equal(r('state.battle.deck[0].name'),'Serra Angel');assert.equal(r('state.battle.resolutionTask'),null);const q=game(true);q(`state.battle.deck=[card('Shock'),card('Divination'),card('Serra Angel')];hand('Serum Visions');playCard(0)`);assert.equal(q('state.battle.hand[0].name'),'Serra Angel');assert.equal(q('state.battle.scry.cards[0].card.name'),'Divination');q('finishScry()');assert.equal(q('state.battle.resolutionTask'),null)});
test('Ward waits after casting costs are paid; declining counters without refund',()=>{const r=game(true);r(`state.battle.enemyCreatures[0].ward=2;globalThis.e=state.battle.enemyCreatures[0];hand('Shock');globalThis.m=state.battle.mana;playCard(0);pick('enemy:'+e.id)`);assert.equal(r('state.battle.mana'),r('m-1'));assert.equal(r('e.health'),50);assert.notEqual(r('state.battle.wardTask'),null);r('answerWard27(false)');assert.equal(r('e.health'),50);assert.equal(r('state.battle.mana'),r('m-1'));assert.equal(r('state.battle.graveyard[0].name'),'Shock');assert.equal(r('state.battle.resolutionTask'),null)});
test('paying numeric Ward resolves the spell and charges only the printed extra amount',()=>{const r=game(true);r(`globalThis.e=state.battle.enemyCreatures[0];e.ward=3;hand('Shock');globalThis.m=state.battle.mana;playCard(0);pick('enemy:'+e.id);answerWard27(true)`);assert.equal(r('e.health'),48);assert.equal(r('state.battle.mana'),r('m-4'))});
test('Ward cannot be paid with insufficient remaining mana, but can be declined',()=>{const r=game(true);r(`state.battle.floatingMana=1;syncMana(state.battle);globalThis.e=state.battle.enemyCreatures[0];e.ward=2;hand('Shock');playCard(0);pick('enemy:'+e.id);answerWard27(true)`);assert.notEqual(r('state.battle.wardTask'),null);assert.equal(r('e.health'),50);r('answerWard27(false)');assert.equal(r('state.battle.resolutionTask'),null)});
test('each Doublecast copy triggers its own Ward payment',()=>{const r=game(true);r(`globalThis.e=state.battle.enemyCreatures[0];e.ward=2;hand('Doublecast','Shock');globalThis.m=state.battle.mana;playCard(0);playCard(0);pick('enemy:'+e.id);answerWard27(true)`);assert.equal(r('e.health'),48);assert.notEqual(r('state.battle.wardTask'),null);r('answerWard27(true)');assert.equal(r('e.health'),46);assert.equal(r('state.battle.mana'),r('m-7'));assert.equal(r('state.battle.graveyard.length'),2)});
test('own Ward does not tax your own buffs and combat does not trigger Ward',()=>{const r=game(true);r(`ally('Tomakul Honor Guard');hand('Battlegrowth');playCard(0);pick('player:a')`);assert.equal(r('state.battle.wardTask'),null);assert.equal(r('state.battle.creatures[0].counterPower'),1)});
test('a countered Aura goes to the graveyard without attaching',()=>{const r=game(true);r(`globalThis.e=state.battle.enemyCreatures[0];e.ward=2;hand('Holy Strength');playCard(0);pick('enemy:'+e.id);answerWard27(false)`);assert.equal(r('state.battle.permanents.length'),0);assert.equal(r('state.battle.graveyard[0].name'),'Holy Strength');assert.equal(r('e.power'),1)});
test('Final Judgment exiles both sides without targeting Hexproof or paying Ward',()=>{const r=game(true);r(`ally('Tomakul Honor Guard');state.battle.enemyCreatures.forEach(e=>{e.ward=4;e.hexproof=true});hand('Final Judgment');playCard(0)`);assert.equal(r('state.battle.enemyExile.length'),2);assert.equal(r('state.battle.exile.length'),1);assert.equal(r('state.battle.wardTask'),null);assert.equal(r('state.battle.creatureDiedThisTurn||false'),false)});
test('expanded exile target restrictions distinguish enchantments, artifacts and mana cards',()=>{const r=game(true);r(`ally();state.battle.permanents=[{id:'ant',card:card('Glorious Anthem')},{id:'sword',card:card('Short Sword')}];refreshPermanentEffects()`);assert.equal(r(`ruleTargetOptions('creature-or-enchantment').some(o=>o.key==='permanent:ant')`),true);assert.equal(r(`ruleTargetOptions('creature-or-enchantment').some(o=>o.key==='permanent:sword')`),false);r(`hand('Scour from Existence');playCard(0);pick('permanent:ant')`);assert.equal(r('state.battle.exile[0].name'),'Glorious Anthem');assert.equal(r('state.battle.creatures[0].power'),2)});
test('enemy Mill moves cards to the graveyard once and loses only on a later failed draw',()=>{const r=game(true);r(`state.battle.deck=[card('Shock'),card('Divination'),card('Serra Angel')];globalThis.e=state.battle.enemyCreatures[0];e.pattern=['mill'];e.millAmount=2;state.battle.enemyCreatures=[e];state.battle.turn=2;resolveEnemyIntents();resolveEnemyIntents()`);assert.equal(r('state.battle.deck.length'),1);assert.equal(r('state.battle.graveyard.map(c=>c.name).join()'),'Serra Angel,Divination');r('millLibrary27(8)');assert.equal(r('state.battle.phase'),'main');r('drawOneCard()');assert.equal(r('state.battle.phase'),'complete')});
test('elite opponents have Ward and milling wisps show an explicit Mill intention',()=>{const r=game(true);r(`state.node=3;globalThis.foes=createEnemyTeam(ENCOUNTERS[2])`);assert.equal(r(`foes.some(e=>wardCost(e)>0)`),true);const q=game(true);q(`globalThis.e=state.battle.enemyCreatures[0];e.pattern=['mill'];e.millAmount=2`);assert.equal(q('enemyIntent(e).kind'),'mill');assert.equal(q('creatureCanAttack(e,state.battle.turn)'),false)});
test('Ward protects an ally from a targeted Rune bolt when the enemy cannot pay it',()=>{const r=game(true);r(`ally('Tomakul Honor Guard');state.battle.enemyCreatures=[{id:'r',owner:'enemy',card:{name:'Rune Raider'},health:20,maxHealth:20,power:3,pattern:['rune'],runeMana:1}];resolveEnemyIntents()`);assert.equal(r('state.battle.creatures[0].damage||0'),0);const q=game(true);q(`ally();state.battle.creatures[0].toughness=4;state.battle.enemyCreatures=[{id:'r',owner:'enemy',card:{name:'Rune Raider'},health:20,maxHealth:20,power:3,pattern:['rune'],runeMana:1}];resolveEnemyIntents()`);assert.equal(q('state.battle.creatures[0].damage'),2)});
test('Su-Chi gives eight mana on death or sacrifice, never on exile',()=>{const r=game(true);r(`ally('Su-Chi Cave Guard');globalThis.m=state.battle.mana;state.battle.resolvingSpellTarget={side:'player',id:'a'};removeSpellTarget('destroy')`);assert.equal(r('state.battle.mana-m'),8);const q=game(true);q(`ally('Su-Chi Cave Guard');globalThis.m=state.battle.mana;state.battle.resolvingSpellTarget={side:'player',id:'a'};removeSpellTarget('exile')`);assert.equal(q('state.battle.mana-m'),0)});
test('every completed starter deck has exactly one Booster Tutor, excluded from ordinary packs',()=>{const r=game(true);r(`state.deck=[];state.battle=null;state.landPool=FALLBACK_LANDS;state.packs=Array.from({length:6},()=>[card('Grizzly Bears')]);state.selection=new Map(Array.from({length:6},(_,i)=>[i,0]));state.activePack=5;state.draftKind='starter';confirmDraft()`);assert.equal(r(`state.deck.filter(c=>c.name==='Booster Tutor').length`),1);assert.equal(r('state.deck.length'),17);r(`state.pool=[card('Grizzly Bears')];globalThis.packs=makeStarterPacks()`);assert.equal(r(`packs.flat().some(c=>c.name==='Booster Tutor')`),false)});
test('Booster Tutor pauses the same battle, adds one card only to hand and resumes its priority window',()=>{const r=game(true);r(`state.pool=['Serra Angel','Veteran Cavalier','Vigilant Baloth','Abbey Griffin','Serra Sphinx','Armored Griffin','Tomakul Honor Guard'].map(card);state.battle.phase='blocks';globalThis.b=state.battle;globalThis.turn=b.turn;globalThis.callback=()=>{};b.priorityCallback=callback;globalThis.beforeDeck=state.deck.length;hand('Booster Tutor');playCard(0)`);assert.equal(r('state.screen'),'draft-screen');assert.equal(r('b.interruption'),true);assert.equal(r('b.phase'),'blocks');assert.equal(r('b.turn'),r('turn'));r(`globalThis.chosen=state.packs[0][0];state.boosterSealed=false;state.selection.set(0,0);confirmDraft()`);assert.equal(r('state.screen'),'combat-screen');assert.equal(r('state.battle===b'),true);assert.equal(r('b.hand[0].name'),r('chosen.name'));assert.equal(r('state.deck.length'),r('beforeDeck'));assert.equal(r('b.priorityCallback===callback'),true);assert.equal(r('b.resolutionTask'),null)});
test('Doublecast Booster Tutor opens two separate boosters and resumes only after both choices',()=>{const r=game(true);r(`hand('Doublecast','Booster Tutor');playCard(0);playCard(0);state.boosterSealed=false;state.selection.set(0,0);confirmDraft()`);assert.notEqual(r('state.boosterInterruption'),null);assert.equal(r('state.battle.hand.length'),1);r(`state.boosterSealed=false;state.selection.set(0,0);confirmDraft()`);assert.equal(r('state.boosterInterruption'),null);assert.equal(r('state.battle.hand.length'),2);assert.equal(r('state.screen'),'combat-screen')});
test('paid specialised shop booster gives all seven once and preserves both offer sets',()=>{const r=game(true);r(`state.node=2;state.coins=100;showShop();state.shop.packs=[{type:'creature',sold:false},{type:'instant',sold:false}];globalThis.before=state.deck.length;globalThis.offers=state.shop.offers.map(o=>o.card.id).join();buyShopPack34(0)`);assert.equal(r('state.coins'),76);assert.equal(r('state.packs[0].every(isCreature)'),true);assert.equal(r('confirmDraft()'),false);r(`state.boosterSealed=false;renderDraft();confirmDraft()`);assert.equal(r('state.deck.length-before'),7);assert.equal(r('state.screen'),'shop-screen');assert.equal(r('state.shop.offers.map(o=>o.card.id).join()'),r('offers'));assert.equal(r('buyShopPack34(0)'),false);r('showJourney();showShop()');assert.equal(r('state.shop.packs[0].sold'),true);assert.equal(r('state.shop.packs.length'),2);assert.equal(r('state.coins'),76)});
test('interruption boosters include one mana card and cannot contain Booster Tutor itself',()=>{const r=game(true);r(`hand('Booster Tutor');playCard(0)`);assert.equal(r('state.packs[0].length'),7);assert.equal(r('state.packs[0].filter(isLand).length'),1);assert.equal(r(`state.packs[0].some(c=>c.name==='Booster Tutor')`),false)});
test('a timed combat continuation stays deferred throughout a Booster Tutor interruption',()=>{const r=game(true);r(`state.battle.phase='attack';state.battle.hand=[];queuedTimers.length=0;globalThis.beats=0;afterCombatBeat(state.battle,'attack',()=>beats++);hand('Booster Tutor');playCard(0);queuedTimers.shift()()`);assert.equal(r('beats'),0);assert.notEqual(r('state.battle.deferredBeat'),null);r(`state.boosterSealed=false;state.selection.set(0,state.packs[0].findIndex(c=>isCreature(c)));confirmDraft()`);assert.equal(r('state.battle.phase'),'attack');assert.equal(r('state.boosterInterruption'),null);r(`if(state.battle.priorityCallback){state.battle.priorityCallback();}else{queuedTimers.shift()();}`);assert.equal(r('beats'),1)});

test('specialised packs contain seven unique matching cards and a real Mythic print',()=>{const r=game(true);for(const type of ['mythic','equipment','instant','creature']){const cards=JSON.parse(r(`JSON.stringify(buildShopPack('${type}'))`));assert.equal(cards.length,7);assert.equal(new Set(cards.map(c=>c.name)).size,7);assert.ok(cards.every(c=>c.verified));if(type==='mythic'){assert.ok(cards.some(c=>c.rarity==='mythic'));assert.ok(cards.every(c=>['mythic','rare','uncommon'].includes(c.rarity)))}else assert.ok(cards.every(c=>new RegExp(type==='equipment'?'Equipment':type==='instant'?'Instant':'Creature').test(c.type_line)))}});
test('Dark Ritual is generic floating mana, copies correctly and expires after the turn',()=>{const r=game(true);r(`state.battle.floatingMana=4;syncMana(state.battle);hand('Dark Ritual');playCard(0)`);assert.equal(r('state.battle.floatingMana'),6);assert.equal(r('state.battle.maxMana'),0);r(`hand('Doublecast','Dark Ritual');playCard(0);playCard(0)`);assert.equal(r('state.battle.floatingMana'),9);r(`state.battle.enemyCreatures=[];state.battle.phase='damage';state.battle.enemyCreatures=[{id:'still',owner:'enemy',card:card('Grizzly Bears'),power:0,health:20,maxHealth:20,summoningSick:true,summonedTurn:99,pattern:['rest']}];resolveEnemyCombat()`);assert.equal(r('state.battle.floatingMana'),0)});
test('camp tokens carry until spent and Treasure does not create permanent mana',()=>{const r=game(true);r(`state.screen='journey-screen';state.campTokens=[];grantCampToken('treasure');grantCampToken('clue');beginBattle(1)`);assert.equal(r('state.battle.hand.length'),7);assert.equal(r('state.battle.permanents.length'),2);r(`globalThis.id=state.battle.permanents.find(p=>p.card.tokenKind==='treasure').id;activatePermanent(id)`);assert.equal(r('state.battle.floatingMana'),1);assert.equal(r('state.battle.maxMana'),0);assert.equal(r('state.campTokens.length'),1);assert.equal(r('activatePermanent(id)'),false);r('beginBattle(2)');assert.equal(r('state.battle.permanents.length'),1);assert.equal(r('state.battle.permanents[0].card.tokenKind'),'clue')});
test('Food and Clue pay two, consume once, and tokens never enter the graveyard',()=>{for(const kind of ['food','clue']){const r=game(true);r(`state.screen='journey-screen';state.campTokens=[];grantCampToken('${kind}');beginBattle(1);state.battle.floatingMana=1;syncMana(state.battle);globalThis.id=state.battle.permanents[0].id`);assert.equal(r('activatePermanent(id)'),false);r('state.battle.floatingMana=2;syncMana(state.battle);globalThis.life=state.playerHealth;globalThis.n=state.battle.hand.length;activatePermanent(id)');assert.equal(r('state.campTokens.length'),0);assert.equal(r('state.battle.graveyard.length'),0);assert.equal(r('state.battle.floatingMana'),0);assert.equal(r(kind==='food'?'state.playerHealth-life':'state.battle.hand.length-n'),kind==='food'?3:1)}});
test('Disenchant restricts targets, removes attached bonuses and permanently destroys a camp token',()=>{const r=game(true);r(`state.screen='journey-screen';state.campTokens=[];grantCampToken('food');beginBattle(1);state.battle.floatingMana=30;syncMana(state.battle);ally();state.battle.permanents.push({id:'sword',card:card('Greatsword'),attachedTo:'a'});refreshPermanentEffects()`);assert.equal(r('state.battle.creatures[0].power'),5);r(`hand('Disenchant');playCard(0)`);assert.equal(r(`choiceOptions(state.battle.choice).some(o=>o.key==='player:a')`),false);r(`pick('permanent:sword')`);assert.equal(r('state.battle.creatures[0].power'),2);r(`hand('Naturalize');playCard(0);pick('permanent:'+state.battle.permanents[0].id)`);assert.equal(r('state.campTokens.length'),0);assert.equal(r('state.battle.graveyard.some(c=>c.campToken)'),false)});

test('fourteen foes vary reproducibly without premature elites or duplicate teams',()=>{const r=game(true);r(`globalThis.seed=17;Math.random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};globalThis.seen=new Set();globalThis.ok=true;for(let n=1;n<=4;n++)for(let k=0;k<150;k++){state.node=n;const team=createEnemyTeam(ENCOUNTERS[n-1]);team.forEach(e=>seen.add(e.kind));if(team.length!==[2,2,3,2][n-1]||new Set(team.map(e=>e.kind)).size!==team.length)ok=false;if(n===1&&team.some(e=>e.tier!=='skirmish'||e.hexproof||e.deathtouch||wardCost(e)))ok=false;if(n<4&&team.some(e=>e.tier==='boss'))ok=false;if(n===4&&team.filter(e=>e.tier==='boss').length!==1)ok=false;}`);assert.equal(r('ok'),true);assert.equal(r('seen.size'),14)});
test('Mend restores only the weakest living ally, caps healing and resolves once',()=>{const r=game(true);r(`const b=state.battle;b.turn=1;const healer=createFoe('sprite',3),weak=createFoe('bulwark',3),other=createFoe('wolf',3);weak.health=2;weak.pattern=['attack'];other.health=10;other.pattern=['attack'];b.enemyCreatures=[healer,weak,other];resolveEnemyIntents();globalThis.h=weak.health;resolveEnemyIntents()`);assert.equal(r('h'),5);assert.equal(r('state.battle.enemyCreatures[1].health'),5);r(`state.battle.turn=4;state.battle.enemyCreatures[1].health=24;state.battle.enemyCreatures[2].health=0;resolveEnemyIntents()`);assert.equal(r('state.battle.enemyCreatures[1].health'),25);assert.equal(r('state.battle.enemyCreatures[2].health'),0)});
test('Rally strengthens living allies once and does not deal attack damage by itself',()=>{const r=game(true);r(`const b=state.battle;b.turn=1;b.enemyCreatures=[createFoe('tyrant',4),createFoe('boar',4)];b.enemyCreatures[1].pattern=['attack'];globalThis.before=state.playerHealth;resolveEnemyIntents();resolveEnemyIntents()`);assert.equal(r('state.battle.enemyCreatures[0].power'),7);assert.equal(r('state.battle.enemyCreatures[1].power'),4);assert.equal(r('state.playerHealth'),r('before'));assert.equal(r(`creatureCanAttack(state.battle.enemyCreatures[0],1)`),false)});
test('new caster intents respect Ward and do not attack during rune or mill actions',()=>{const r=game(true);r(`const b=state.battle;b.turn=1;b.enemyCreatures=[createFoe('archivist',3)];ally('Su-Chi Cave Guard');resolveEnemyIntents()`);assert.equal(r('state.battle.creatures[0].damage||0'),0);assert.equal(r('enemyIntent(state.battle.enemyCreatures[0]).kind'),'rune');assert.equal(r('creatureCanAttack(state.battle.enemyCreatures[0],1)'),false);r(`state.battle.turn=2;globalThis.left=state.battle.deck.length;resolveEnemyIntents();resolveEnemyIntents()`);assert.equal(r('left-state.battle.deck.length'),1);assert.equal(r('state.battle.graveyard.length'),1)});

test('flying enemies accept attacks only from Flying or Reach, including granted keywords',()=>{const r=game(true);r(`ally();globalThis.a=state.battle.creatures[0];globalThis.e=state.battle.enemyCreatures[0];e.flying=true`);assert.equal(r('canAttackEnemy(a,e)'),false);r('a.reach=true');assert.equal(r('canAttackEnemy(a,e)'),true);r('a.reach=false;a.temporaryKeywords=["flying"]');assert.equal(r('canAttackEnemy(a,e)'),true);r('a.temporaryKeywords=[];a.permanentKeywords=["reach"]');assert.equal(r('canAttackEnemy(a,e)'),true);r('a.permanentKeywords=[];e.flying=false');assert.equal(r('canAttackEnemy(a,e)'),true);});
test('ground creatures choose a legal default target and reject an explicit flying target without side effects',()=>{const r=game(true);r(`ally();globalThis.b=state.battle;globalThis.a=b.creatures[0];b.enemyCreatures[0].flying=true;b.selectedEnemyTargetId=b.enemyCreatures[0].id;globalThis.fly=b.enemyCreatures[0];globalThis.ground=b.enemyCreatures[1]`);assert.equal(r('attackTarget(b,a).id'),r('ground.id'));r('b.mulliganAvailable=true');assert.equal(r('queueCreatureAttack(a.id,fly.id)'),false);assert.equal(r('a.willAttack'),false);assert.equal(r('b.mulliganAvailable'),true);assert.equal(r('queueCreatureAttack(a.id,ground.id)'),true);assert.equal(r('a.attackTargetId'),r('ground.id'));});
test('an attack made illegal before damage is cancelled without tapping or hitting a different foe',()=>{const r=game(true);r(`ally();globalThis.b=state.battle;globalThis.a=b.creatures[0];globalThis.e=b.enemyCreatures[0];queueCreatureAttack(a.id,e.id);e.flying=true;b.phase='attack';resolvePlayerAttacks()`);assert.equal(r('e.health'),50);assert.equal(r('b.enemyCreatures[1].health'),50);assert.equal(r('a.tapped'),false);assert.equal(r('a.attackedThisTurn||false'),false);assert.equal(r('a.willAttack'),false);});
test('the damage resolver and trample cannot bypass flying-target restrictions',()=>{const r=game(true);r(`ally();globalThis.b=state.battle;globalThis.a=b.creatures[0];globalThis.e=b.enemyCreatures[0];e.flying=true;resolveCombatDamage([a],new Map([[a.id,[e]]]),'player')`);assert.equal(r('e.health'),50);assert.equal(r('a.damage||0'),0);r(`e.flying=false;e.health=1;a.trample=true;a.power=5;b.enemyCreatures[1].flying=true;resolveCombatDamage([a],new Map([[a.id,[e]]]),'player')`);assert.equal(r('b.enemyCreatures[0].health'),50);});
test('Ward taps physical lands for the extra cost and cannot charge twice after resolution',()=>{const r=game(true);r(`globalThis.b=state.battle;b.floatingMana=0;while(b.lands.length<6)b.lands.push({id:'extra-'+b.lands.length,card:FALLBACK_LANDS[0],tapped:false});syncMana(b);globalThis.e=b.enemyCreatures[0];e.ward=2;hand('Shock');playCard(0);pick('enemy:'+e.id)`);assert.equal(r('b.lands.filter(l=>l.tapped).length'),1);r('answerWard27(true)');assert.equal(r('b.lands.filter(l=>l.tapped).length'),3);assert.equal(r('b.mana'),3);r('answerWard27(true)');assert.equal(r('b.lands.filter(l=>l.tapped).length'),3);});
test('Ward spends floating mana first and failed payments leave all sources unchanged',()=>{const r=game(true);r(`globalThis.b=state.battle;b.lands=Array.from({length:2},(_,i)=>({id:'land-'+i,card:FALLBACK_LANDS[0],tapped:false}));b.floatingMana=2;syncMana(b);globalThis.e=b.enemyCreatures[0];e.ward=2;hand('Shock');playCard(0);pick('enemy:'+e.id);answerWard27(true)`);assert.equal(r('b.floatingMana'),0);assert.equal(r('b.lands.filter(l=>l.tapped).length'),1);const q=game(true);q(`globalThis.b=state.battle;b.lands=Array.from({length:2},(_,i)=>({id:'land-'+i,card:FALLBACK_LANDS[0],tapped:false}));b.floatingMana=0;syncMana(b);globalThis.e=b.enemyCreatures[0];e.ward=2;hand('Shock');playCard(0);pick('enemy:'+e.id);answerWard27(true)`);assert.equal(q('b.lands.filter(l=>l.tapped).length'),1);assert.equal(q('b.mana'),1);assert.notEqual(q('b.wardTask'),null);q('answerWard27(false)');assert.equal(q('b.lands.filter(l=>l.tapped).length'),1);});


test('double strike keeps its second trample step after the first target dies',()=>{const r=game(true);r(`ally();globalThis.b=state.battle;globalThis.a=b.creatures[0];globalThis.e=b.enemyCreatures[0];e.health=1;e.power=0;a.doubleStrike=true;a.trample=true;a.power=5;resolveCombatDamage([a],new Map([[a.id,[e]]]),'player')`);assert.equal(r('b.enemyCreatures[0].health'),41);});

test('five reviewed counters enter the player pool, while enemy-only sorceries do not',()=>{const r=game(true);for(const name of ['Cancel','Counterspell','Negate','Dispel','Dismiss']){assert.equal(r(`rulesAudit(card(${JSON.stringify(name)})).playable`),true);assert.equal(r(`canCastNow(card(${JSON.stringify(name)}))`),false);}assert.equal(r(`BUNDLED_CARDS.some(c=>c.name==='Lava Spike'||c.name==="Sovereign's Bite")`),false);});
test('Counterspell stops a pending Shock, pays mana once and never kills its caster',()=>{const r=game(true);r(`ally();globalThis.b=state.battle;b.phase='enemy';globalThis.e=createFoe('archivist',3);e.pattern=['rune'];e.hexproof=true;b.enemyCreatures=[e];hand('Counterspell');globalThis.before=b.mana;resolveEnemyIntents();globalThis.s=activeEnemySpell38();playCard(0);pick('spell:'+s.id)`);assert.equal(r('s.status'),'countered');assert.equal(r('b.creatures[0].damage||0'),0);assert.equal(r('e.health'),17);assert.equal(r('b.mana'),r('before-2'));r('resolveEnemySpell38(s);resolveEnemySpell38(s)');assert.equal(r('b.creatures[0].damage||0'),0);assert.equal(r('b.enemySpellGraveyard.length'),1);assert.equal(r('b.graveyard[0].name'),'Counterspell');});
test('uncountered Shock hits its original target only once and respects allied Ward',()=>{const r=game(true);r(`ally('Su-Chi Cave Guard');globalThis.b=state.battle;b.phase='enemy';globalThis.e=createFoe('archivist',3);e.pattern=['rune'];b.enemyCreatures=[e];hand('Counterspell');resolveEnemyIntents();globalThis.s=activeEnemySpell38();resolveEnemySpell38(s);resolveEnemySpell38(s)`);assert.equal(r('s.status'),'countered');assert.equal(r('b.creatures[0].damage||0'),0);const q=game(true);q(`ally('Serra Angel');globalThis.b=state.battle;b.phase='enemy';globalThis.e=createFoe('archivist',3);e.pattern=['rune'];b.enemyCreatures=[e];hand('Counterspell');resolveEnemyIntents();globalThis.s=activeEnemySpell38();resolveEnemySpell38(s);resolveEnemySpell38(s)`);assert.equal(q('b.creatures[0].damage'),2);assert.equal(q('s.status'),'resolved');});
test('Dispel rejects sorceries; Negate stops Lava Spike before life is lost',()=>{const r=game(true);r(`globalThis.b=state.battle;b.phase='enemy';globalThis.e=createFoe('duelist',2);e.pattern=['scorch'];b.enemyCreatures=[e];hand('Dispel','Negate');globalThis.life=state.playerHealth;resolveEnemyIntents();globalThis.s=activeEnemySpell38()`);assert.equal(r(`canCastNow(card('Dispel'))`),false);assert.equal(r(`canCastNow(card('Negate'))`),true);r(`playCard(1);pick('spell:'+s.id);resolveEnemySpell38(s)`);assert.equal(r('state.playerHealth'),r('life'));assert.equal(r('s.status'),'countered');});
test('Dismiss counters and draws one; copied counters fizzle after that target is countered',()=>{const r=game(true);r(`globalThis.b=state.battle;b.phase='enemy';globalThis.e=createFoe('raider',2);e.pattern=['rune'];b.enemyCreatures=[e];hand('Dismiss');b.copyNextSpell=1;globalThis.count=b.deck.length;resolveEnemyIntents();globalThis.s=activeEnemySpell38();playCard(0);pick('spell:'+s.id)`);assert.equal(r('b.hand.length'),1);assert.equal(r('b.deck.length'),r('count-1'));assert.equal(r('b.enemySpellGraveyard.length'),1);assert.equal(r('b.resolutionTask'),null);});
test('enemy spells remain independent of their caster, but fizzle if their target gains Hexproof',()=>{const r=game(true);r(`ally('Serra Angel');globalThis.b=state.battle;b.phase='enemy';globalThis.e=createFoe('archivist',3);e.pattern=['rune'];b.enemyCreatures=[e];hand('Counterspell');resolveEnemyIntents();globalThis.s=activeEnemySpell38();b.enemyCreatures=[];winBattle()`);assert.equal(r('b.phase'),'enemy');r('resolveEnemySpell38(s)');assert.equal(r('b.creatures[0].damage'),2);const q=game(true);q(`ally();globalThis.b=state.battle;b.phase='enemy';globalThis.e=createFoe('archivist',3);e.pattern=['rune'];b.enemyCreatures=[e];hand('Snakeskin Veil');resolveEnemyIntents();globalThis.s=activeEnemySpell38();b.creatures[0].hexproof=true;resolveEnemySpell38(s)`);assert.equal(q('s.status'),'fizzled');assert.equal(q('b.creatures[0].damage||0'),0);});
test('multiple enemy spells use separate instant windows and resume combat exactly once',()=>{const r=game(true);r(`ally('Serra Angel');globalThis.b=state.battle;b.phase='enemy';b.enemyCreatures=['archivist','raider'].map(kind=>{const e=createFoe(kind,3);e.pattern=['rune'];return e});hand('Dispel');resolveEnemyIntents();globalThis.done=0;afterCombatBeat(b,'enemy',()=>done++);globalThis.first=activeEnemySpell38();playCard(0);pick('spell:'+first.id);handleCombatAction()`);assert.equal(r('first.status'),'countered');assert.notEqual(r('activeEnemySpell38().id'),r('first.id'));r(`globalThis.timer=queuedTimers.shift();timer();while(queuedTimers.length)queuedTimers.shift()()`);assert.equal(r('b.creatures[0].damage'),2);assert.equal(r('done'),1);assert.equal(r('activeEnemySpell38()'),null);});
test('uncountered sorceries resolve once; Mill and normal attacks are not counterspell targets',()=>{const r=game(true);r(`globalThis.b=state.battle;b.phase='enemy';globalThis.e=createFoe('vampire',3);e.pattern=['drain'];e.health=10;b.enemyCreatures=[e];hand('Dispel');globalThis.life=state.playerHealth;resolveEnemyIntents();resolveEnemyIntents()`);assert.equal(r('state.playerHealth'),r('life-3'));assert.equal(r('e.health'),13);assert.equal(r(`canCastNow(card('Dispel'))`),false);r(`b.turn++;e.pattern=['mill'];e.millAmount=2;hand('Counterspell');resolveEnemyIntents()`);assert.equal(r('pendingEnemySpells38().length'),0);assert.equal(r(`canCastNow(card('Counterspell'))`),false);});

test('a counter response is offered when an untapped mana creature can pay the missing mana',()=>{const r=game(true);r(`ally('Llanowar Elves');globalThis.b=state.battle;b.phase='enemy';b.lands=[{id:'land',card:FALLBACK_LANDS[0],tapped:false}];b.floatingMana=0;syncMana(b);globalThis.e=createFoe('archivist',3);e.pattern=['rune'];b.enemyCreatures=[e];hand('Counterspell');resolveEnemyIntents();globalThis.s=activeEnemySpell38()`);assert.equal(r('s.status'),'pending');assert.equal(r('hasInstantResponse(b)'),true);r(`tapForMana('a');playCard(0);pick('spell:'+s.id)`);assert.equal(r('s.status'),'countered');assert.equal(r('b.mana'),0);assert.equal(r('b.creatures[0].tapped'),true);});
test('Dismiss counters before its empty-library draw ends the run',()=>{const r=game(true);r(`globalThis.b=state.battle;b.phase='enemy';b.deck=[];globalThis.e=createFoe('archivist',3);e.pattern=['rune'];b.enemyCreatures=[e];hand('Dismiss');resolveEnemyIntents();globalThis.s=activeEnemySpell38();playCard(0);pick('spell:'+s.id)`);assert.equal(r('s.status'),'countered');assert.equal(r('b.phase'),'complete');assert.equal(r('b.resolutionTask'),null);});

function counterGame44(){const r=game(true);r(`globalThis.b=state.battle;b.turn=2;b.phase='main';globalThis.e=createFoe('archivist',3);e.ward=0;e.health=e.maxHealth=50;b.enemyCreatures=[e];`);return r;}
test('counter readiness is restricted to later casters on even turns',()=>{const r=game(true);assert.equal(r(`createFoe('archivist',2).counterspell`),false);assert.equal(r(`createFoe('sphinx',4).counterspell`),true);r(`globalThis.e=createFoe('archivist',3);state.battle.turn=1`);assert.equal(r('enemyCounterReady44(e)'),false);r('state.battle.turn=2');assert.equal(r('enemyCounterReady44(e)'),true);r('state.battle.enemyCounterUsedTurn=2');assert.equal(r('enemyCounterReady44(e)'),false);});
test('enemy Counterspell stops a paid creature once per turn, with no refund',()=>{const r=counterGame44();r(`hand('Grizzly Bears','Grizzly Bears');globalThis.m=b.mana;playCard(0,'player');globalThis.cs=activeEnemySpell38()`);assert.equal(r('b.creatures.length'),0);assert.equal(r('b.mana'),r('m-2'));assert.equal(r('cs.card.name'),'Counterspell');assert.equal(r('cs.manaPaid'),2);assert.equal(r('cs.manaRemaining'),0);r('handleCombatAction()');assert.equal(r('b.enemyCounterWindow'),null);assert.equal(r('b.graveyard.length'),1);assert.equal(r('b.creatures.length'),0);r(`playCard(0,'player')`);assert.equal(r('b.creatures.length'),1);assert.equal(r('b.mana'),r('m-4'));assert.equal(r('b.enemySpellGraveyard.length'),1);});
test('a countered draw spell has no draw effect and all casting costs remain paid',()=>{const r=counterGame44();r(`hand('Divination');globalThis.n=b.deck.length;globalThis.m=b.mana;playCard(0);handleCombatAction()`);assert.equal(r('b.hand.length'),0);assert.equal(r('b.deck.length'),r('n'));assert.equal(r('b.mana'),r('m-3'));assert.equal(r('b.resolutionTask'),null);});
test('a player Counterspell can save the original spell without repaying its cost',()=>{const r=counterGame44();r(`hand('Shock','Counterspell');globalThis.m=b.mana;playCard(0);pick('enemy:'+e.id);globalThis.cs=activeEnemySpell38();playCard(0);pick('spell:'+cs.id)`);assert.equal(r('cs.status'),'countered');assert.equal(r('e.health'),50);assert.equal(r('b.enemyCounterWindow.card.name'),'Shock');r('handleCombatAction()');assert.equal(r('e.health'),48);assert.equal(r('b.mana'),r('m-3'));assert.equal(r('b.graveyard.length'),2);assert.equal(r('b.resolutionTask'),null);});
test('Dismiss responds to Counterspell, draws one and resumes the pending draw spell',()=>{const r=counterGame44();r(`hand('Divination','Dismiss');globalThis.n=b.deck.length;playCard(0);globalThis.cs=activeEnemySpell38();playCard(0);pick('spell:'+cs.id)`);assert.equal(r('b.hand.length'),1);r('handleCombatAction()');assert.equal(r('b.hand.length'),3);assert.equal(r('b.deck.length'),r('n-3'));});
test('one enemy Counterspell counters only one resolution of a copied spell',()=>{const r=counterGame44();r(`hand('Divination');b.copyNextSpell=1;globalThis.m=b.mana;playCard(0);handleCombatAction()`);assert.equal(r('b.hand.length'),2);assert.equal(r('b.mana'),r('m-3'));assert.equal(r('b.graveyard.length'),1);});
test('sacrifice costs stay paid when the enemy counters Village Rites',()=>{const r=counterGame44();r(`ally();hand('Village Rites');playCard(0);pick('a')`);assert.equal(r('b.creatures.length'),0);assert.equal(r('b.enemyCounterWindow.card.name'),'Village Rites');r('handleCombatAction()');assert.equal(r('b.hand.length'),0);assert.equal(r(`b.graveyard.map(c=>c.name).sort().join()`),'Grizzly Bears,Village Rites');});
test('enemy Counterspell handles Auras, Equipment and Clone before they enter',()=>{for(const name of ['Holy Strength','Bone Saw','Clone']){const r=counterGame44();r(`ally();hand(${JSON.stringify(name)});playCard(0,'player');if(b.choice)pick('player:a');handleCombatAction()`);assert.equal(r('b.creatures.length'),1,name);assert.equal(r('b.permanents.length'),0,name);assert.equal(r('b.graveyard.length'),1,name);assert.equal(r('b.graveyard[0].name'),name);}});
test('mana cards and mana abilities do not consume the enemy counter; noninstants wait during the window',()=>{const r=counterGame44();r(`b.hand=[{...FALLBACK_LANDS[0],runMana:true}];playCard(0,'player')`);assert.equal(r('b.enemyCounterWindow||null'),null);assert.equal(r('enemyCounterReady44(e)'),true);r(`hand('Divination','Grizzly Bears');playCard(0)`);assert.equal(r(`canCastNow(card('Grizzly Bears'))`),false);r(`ally('Llanowar Elves');tapForMana('a')`);assert.equal(r('b.enemyCounterUsedTurn'),2);assert.equal(r('b.enemyCounterWindow.card.name'),'Divination');});
test('killing the counter caster does not remove its pending Counterspell or finish the battle early',()=>{const r=counterGame44();r(`hand('Divination','Murder');globalThis.n=b.deck.length;playCard(0);globalThis.cs=activeEnemySpell38();playCard(0);pick('enemy:'+e.id)`);assert.equal(r('b.enemyCreatures.length'),0);assert.equal(r('b.phase'),'main');assert.equal(r('cs.status'),'pending');r('handleCombatAction()');assert.equal(r('cs.status'),'resolved');assert.equal(r('b.deck.length'),r('n'));assert.equal(r('b.phase'),'complete');});
test('countering the enemy response restores the original enemy-spell priority window exactly once',()=>{const r=counterGame44();r(`b.phase='enemy';e.pattern=['rune'];hand('Counterspell','Dispel');resolveEnemyIntents();globalThis.original=activeEnemySpell38();globalThis.done=0;afterCombatBeat(b,'enemy',()=>done++);playCard(0);pick('spell:'+original.id);globalThis.cs=activeEnemySpell38();playCard(0);pick('spell:'+cs.id);handleCombatAction()`);assert.equal(r('original.status'),'countered');assert.equal(r('activeEnemySpell38().id'),r('original.id'));r('handleCombatAction();while(queuedTimers.length)queuedTimers.shift()()');assert.equal(r('done'),1);});
test('Booster Tutor preserves the enemy counter window and can find a response',()=>{const r=counterGame44();r(`hand('Divination','Booster Tutor');playCard(0);globalThis.savedWindow44=b.enemyCounterWindow;playCard(0)`);assert.equal(r('state.screen'),'draft-screen');assert.equal(r('b.enemyCounterWindow===savedWindow44'),true);r(`state.packs[0][0]=card('Counterspell');state.boosterSealed=false;state.selection.set(0,0);confirmDraft()`);assert.equal(r('b.enemyCounterWindow===savedWindow44'),true);r(`playCard(0);pick('spell:'+savedWindow44.spell.id);handleCombatAction()`);assert.equal(r('b.hand.length'),2);assert.equal(r('b.enemyCounterWindow'),null);});

test('stopping the enemy counter does not waive the original target Ward payment',()=>{const r=counterGame44();r(`e.ward=2;hand('Shock','Counterspell');globalThis.m=b.mana;playCard(0);pick('enemy:'+e.id);globalThis.cs=activeEnemySpell38()`);assert.equal(r('b.wardTask||null'),null);r(`playCard(0);pick('spell:'+cs.id);handleCombatAction()`);assert.notEqual(r('b.wardTask'),null);assert.equal(r('b.mana'),r('m-3'));r('answerWard27(true)');assert.equal(r('b.mana'),r('m-5'));assert.equal(r('e.health'),48);});
test('scry responses cannot accidentally pass priority while their choice remains open',()=>{const r=counterGame44();r(`hand('Divination','Opt');playCard(0);playCard(0);globalThis.priority=b.priorityCallback;handleCombatAction()`);assert.notEqual(r('b.scry'),null);assert.equal(r('b.priorityCallback===priority'),true);assert.equal(r('b.enemyCounterWindow.card.name'),'Divination');r('finishScry();handleCombatAction()');assert.equal(r('b.hand.length'),1);assert.equal(r('b.enemyCounterWindow'),null);});
test('a timed combat continuation waits for the enemy counter window and resumes once',()=>{const r=counterGame44();r(`b.phase='attack';hand();queuedTimers.length=0;globalThis.beats=0;afterCombatBeat(b,'attack',()=>beats++);hand('Shock');playCard(0);pick('enemy:'+e.id);queuedTimers.shift()()`);assert.equal(r('beats'),0);assert.notEqual(r('b.deferredBeat'),null);r('handleCombatAction();while(queuedTimers.length)queuedTimers.shift()()');assert.equal(r('beats'),1);});

test('an Aura whose host leaves during the counter window goes to the graveyard when resumed',()=>{const r=counterGame44();r(`ally();hand('Holy Strength','Village Rites','Dispel');playCard(0);pick('player:a');playCard(0);pick('a');playCard(0);pick('spell:'+b.enemyCounterWindow.spell.id);handleCombatAction()`);assert.equal(r('b.creatures.length'),0);assert.equal(r('b.permanents.length'),0);assert.equal(r(`b.graveyard.filter(c=>c.name==='Holy Strength').length`),1);assert.equal(r('b.enemyCounterWindow'),null);});

function waveGame45(node=3){const r=game(true);r(`state.pool=playableCards(BUNDLED_CARDS);state.deck=Array(40).fill(card('Grizzly Bears'));beginBattle(${node});globalThis.b=state.battle;b.floatingMana=30;syncMana(b);b.hand=[];globalThis.clearWave=()=>{for(const foe of [...b.enemyCreatures])damageFirstEnemy(1000,foe);winBattle()};`);return r;}
test('only fights three and four have two waves, with the boss reserved for the final wave',()=>{for(const node of [1,2,3,4]){const r=waveGame45(node);assert.equal(r('b.waves.length'),node<3?1:2);assert.equal(r('b.enemyCreatures.length'),2);assert.equal(r('b.waves[0].some(e=>e.tier===\'boss\')'),false);if(node===3)assert.equal(r('b.waves[1].every(e=>e.tier===\'elite\')'),true);if(node===4){assert.equal(r('b.waves[1].filter(e=>e.tier===\'boss\').length'),1);assert.equal(r('b.bossName'),r('b.waves[1].find(e=>e.tier===\'boss\').card.name'));}assert.equal(r('new Set(b.waves.flat().map(e=>e.id)).size'),r('b.waves.flat().length'));}});
test('clearing a wave in main preserves the hand, library, board, mana and turn',()=>{const r=waveGame45();r(`ally('Serra Angel');b.permanents=[{id:'sword',card:card('Short Sword'),attachedTo:'a'}];refreshPermanentEffects();globalThis.unit=b.creatures[0];unit.tapped=true;unit.attackedThisTurn=true;unit.damage=1;globalThis.sword=b.permanents[0];hand('Divination');b.lands=[{id:'land',card:FALLBACK_LANDS[0],tapped:true}];b.floatingMana=2;b.landAvailable=false;syncMana(b);state.playerHealth=42;globalThis.deckCount=b.deck.length;globalThis.old=b.enemyCreatures.map(e=>e.id);globalThis.coins=state.coins;clearWave()`);assert.equal(r('b.waveIndex'),1);assert.equal(r('state.node'),3);assert.equal(r('b.turn'),1);assert.equal(r('state.playerHealth'),42);assert.equal(r('b.hand[0].name'),'Divination');assert.equal(r('b.hand.length'),1);assert.equal(r('b.deck.length'),r('deckCount'));assert.equal(r('b.creatures[0]===unit&&b.permanents[0]===sword'),true);assert.equal(r('unit.tapped&&unit.attackedThisTurn'),true);assert.equal(r('unit.damage'),1);assert.equal(r('b.floatingMana'),2);assert.equal(r('b.lands[0].tapped'),true);assert.equal(r('b.landAvailable'),false);assert.equal(r('b.creatureDiedThisTurn'),true);assert.ok(r('state.coins>coins'));assert.equal(r('b.enemyCreatures.every(e=>!old.includes(e.id)&&isSummoningSick(e,b.turn))'),true);});
test('a combat clear finishes the turn once, untaps and draws only one card',()=>{const r=waveGame45();r(`ally();globalThis.a=b.creatures[0];a.tapped=true;a.attackedThisTurn=true;a.damage=1;a.power+=3;a.toughness+=3;b.turnEffects=[{creatureId:a.id,power:3,toughness:3}];b.lands=[{id:'land',card:FALLBACK_LANDS[0],tapped:true}];b.turn=2;b.phase='damage';b.floatingMana=3;globalThis.n=b.deck.length;globalThis.hp=state.playerHealth;b.priorityCallback=()=>{};clearWave()`);assert.equal(r('b.turn'),3);assert.equal(r('b.phase'),'main');assert.equal(r('b.hand.length'),1);assert.equal(r('b.deck.length'),r('n-1'));assert.equal(r('state.playerHealth'),r('hp'));assert.equal(r('a.tapped||a.attackedThisTurn'),false);assert.equal(r('a.power'),2);assert.equal(r('a.damage'),0);assert.equal(r('b.floatingMana'),0);assert.equal(r('b.landAvailable'),true);assert.equal(r('b.priorityCallback'),null);assert.equal(r('b.enemyCreatures.every(e=>e.summonedTurn===3&&!creatureCanAttack(e,3))'),true);});
test('the reward and encounter advancement occur only after the final wave and only once',()=>{const r=waveGame45();r('clearWave();winBattle()');assert.equal(r('state.node'),3);assert.equal(r('b.waveIndex'),1);assert.equal(r('state.screen'),'combat-screen');r('clearWave();globalThis.c=state.coins;winBattle()');assert.equal(r('state.node'),4);assert.equal(r('state.screen'),'draft-screen');assert.equal(r('b.phase'),'complete');assert.equal(r('state.packs[0].length'),7);assert.equal(r('state.coins'),r('c'));});
test('boss victory waits until the final wave is cleared',()=>{const r=waveGame45(4);r('globalThis.name=b.bossName;clearWave()');assert.equal(r('state.screen'),'combat-screen');assert.equal(r('b.waveIndex'),1);assert.equal(r('b.enemyCreatures.some(e=>e.tier===\'boss\'&&e.card.name===name)'),true);r('clearWave()');assert.equal(r('state.screen'),'end-screen');assert.equal(r('b.phase'),'complete');});
test('copied mass exile finishes all copies before the next wave arrives',()=>{const r=waveGame45();r(`b.copyNextSpell=1;hand('Final Judgment');globalThis.n=b.deck.length;playCard(0)`);assert.equal(r('b.waveIndex'),1);assert.equal(r('b.enemyExile.length'),2);assert.equal(r('b.enemyCreatures.length'),2);assert.equal(r('b.enemyCreatures.every(e=>e.health===e.maxHealth)'),true);assert.equal(r('b.deck.length'),r('n'));assert.equal(r('b.graveyard.length'),1);assert.equal(r('b.creatureDiedThisTurn||false'),false);});
test('enemy Counterspell and the original player spell finish before wave advancement',()=>{const r=waveGame45();r(`b.turn=2;b.enemyCreatures[0].counterspell=true;hand('Divination','Murder','Murder','Dispel');globalThis.n=b.deck.length;playCard(0);globalThis.first=b.enemyCreatures[0].id;playCard(0);pick('enemy:'+first);playCard(0);pick('enemy:'+b.enemyCreatures[0].id);playCard(0);pick('spell:'+b.enemyCounterWindow.spell.id)`);assert.equal(r('b.enemyCreatures.length'),0);assert.equal(r('b.waveIndex'),0);assert.notEqual(r('b.enemyCounterWindow'),null);r('handleCombatAction()');assert.equal(r('b.waveIndex'),1);assert.equal(r('b.hand.length'),2);assert.equal(r('b.deck.length'),r('n-2'));assert.equal(r('b.turn'),2);assert.equal(r('b.enemyCounterUsedTurn'),2);});
test('wave cleanup removes old enemy Auras but preserves player Equipment',()=>{const r=waveGame45();r(`ally();b.permanents=[{id:'rancor',card:card('Rancor'),attachedTo:b.enemyCreatures[0].id},{id:'sword',card:card('Short Sword'),attachedTo:'a'}];globalThis.n=b.deck.length;clearWave()`);assert.equal(r('b.permanents.length'),1);assert.equal(r('b.permanents[0].attachedTo'),'a');assert.equal(r('b.hand[0].name'),'Rancor');assert.equal(r('b.deck.length'),r('n'));});
test('an empty-library draw at a combat wave transition loses instead of refilling',()=>{const r=waveGame45();r(`b.deck=[];b.phase='damage';clearWave()`);assert.equal(r('state.screen'),'end-screen');assert.equal(r('b.phase'),'complete');assert.equal(r('state.node'),3);assert.equal(r('b.deck.length'),0);});

test('direct counter response pays once and resumes the original paid spell only after continuing',()=>{
 const r=counterGame44();r(`hand('Divination','Counterspell');globalThis.m=b.mana;globalThis.n=b.deck.length;playCard(0);globalThis.cs=activeEnemySpell38()`);
 assert.equal(r(`enemyCounterResponses46()[0].card.name`),'Counterspell');
 assert.equal(r(`castEnemyCounterResponse46(0,cs.id,'Counterspell')`),true);
 assert.equal(r('cs.status'),'countered');assert.equal(r('b.mana'),r('m-5'));
 assert.equal(r('b.deck.length'),r('n'));assert.notEqual(r('b.enemyCounterWindow'),null);
 assert.equal(r(`castEnemyCounterResponse46(0,cs.id,'Counterspell')`),false);
 r('handleCombatAction()');assert.equal(r('b.hand.length'),2);assert.equal(r('b.deck.length'),r('n-2'));assert.equal(r('b.mana'),r('m-5'));
});
test('direct counter response rejects insufficient mana, open choices and stale spell IDs',()=>{
 const r=counterGame44();r(`hand('Divination','Counterspell');b.lands=[];b.floatingMana=3;syncMana(b);playCard(0);globalThis.cs=activeEnemySpell38();globalThis.m=b.mana`);
 assert.equal(r('enemyCounterResponses46()[0].payable'),false);
 assert.equal(r(`castEnemyCounterResponse46(0,cs.id,'Counterspell')`),false);assert.equal(r('b.mana'),r('m'));
 r('b.floatingMana=10;syncMana(b)');assert.equal(r(`castEnemyCounterResponse46(0,'stale-id','Counterspell')`),false);
 r('b.choice={};');assert.equal(r('enemyCounterResponses46().length'),0);r('b.choice=null;handleCombatAction()');
 assert.equal(r('b.hand[0].name'),'Counterspell');assert.equal(r('b.enemyCounterWindow'),null);
});
test('direct counter response recommends the cheapest payable legal counter and excludes other instants',()=>{
 const r=counterGame44();r(`hand('Divination','Dismiss','Counterspell','Dispel','Shock');playCard(0)`);
 assert.equal(r(`enemyCounterResponses46().map(item=>item.card.name).join(',')`),'Dispel,Counterspell,Dismiss');
 assert.equal(r(`castEnemyCounterResponse46(3,activeEnemySpell38().id,'Shock')`),false);
 assert.equal(r(`castEnemyCounterResponse46(2,activeEnemySpell38().id,'Dispel')`),true);
 assert.equal(r('activeEnemySpell38().status'),'countered');
});

test('eight new Reach creatures are playable at printed cost and can fight flying foes',()=>{
 for(const name of ['Canopy Spider','Grappler Spider','Thornweald Archer','Kessig Recluse','Rib Cage Spider','Sporecap Spider','Mammoth Spider','Archweaver']){
  const r=game(true);r(`hand(${JSON.stringify(name)});globalThis.c=state.battle.hand[0];globalThis.before=state.battle.mana;playCard(0,'player');globalThis.u=state.battle.creatures[0];globalThis.e=state.battle.enemyCreatures[0];e.flying=true`);
  assert.equal(r('rulesAudit(c).playable'),true,name);assert.equal(r('before-state.battle.mana'),r('c.cmc'),name);
  assert.equal(r('u.power'),r('Number(c.power)'),name);assert.equal(r('u.toughness'),r('Number(c.toughness)'),name);
  assert.equal(r(`hasCreatureKeyword(u,'reach')`),true,name);assert.equal(r('canAttackEnemy(u,e)'),true,name);assert.equal(r('canBlockCreature(u,e)'),true,name);
 }
});

function diceReady50(r){r('finishDiceAnimation50(state.battle.diceRoll.id)');}
function diceContinue50(r){diceReady50(r);r('settleDiceRoll50(state.battle.diceRoll.id)');}
test('D6 boundary values map to faces one through six',()=>{const r=game(true);r('globalThis.samples=[0,.1666666666,1/6,.5,.999999];Math.random=()=>samples.shift()');assert.equal(r('Array.from({length:5},rollD6Value50).join()'),'1,1,2,4,6');});
test('Growth Spurt waits for its visible result, pays once and expires as a temporary bonus',()=>{
 const r=game(true);r(`ally();hand('Growth Spurt');Math.random=()=>.5;globalThis.b=state.battle;globalThis.m=b.mana;playCard(0);pick('player:a');globalThis.id=b.diceRoll.id`);
 assert.equal(r('b.creatures[0].power'),2);assert.equal(r('b.mana'),r('m-2'));assert.equal(r('settleDiceRoll50(id)'),false);
 assert.equal(r('b.diceRoll.results[0]'),4);assert.equal(r('Object.isFrozen(b.diceRoll.results)'),true);
 diceContinue50(r);assert.equal(r('b.creatures[0].power'),6);assert.equal(r('b.creatures[0].toughness'),6);assert.equal(r('b.creatures[0].counterPower||0'),0);assert.equal(r('b.diceHistory[0].results[0]'),4);assert.equal(r('settleDiceRoll50(id)'),false);
 r('expireTurnEffects(b)');assert.equal(r('b.creatures[0].power'),2);assert.equal(r('b.creatures[0].toughness'),2);assert.equal(r('b.resolutionTask'),null);
});
test('the roll is generated once and combat cannot advance while dice are unresolved',()=>{
 const r=game(true);r(`ally();hand('Growth Spurt','Shock');globalThis.rollCalls=0;Math.random=()=>{rollCalls++;return .99};playCard(0);pick('player:a');globalThis.id=state.battle.diceRoll.id;finishTurn();handleCombatAction()`);
 assert.equal(r('rollCalls'),1);assert.equal(r('state.battle.phase'),'main');assert.equal(r(`canCastNow(card('Shock'))`),false);assert.equal(r('finishDiceAnimation50(id)'),true);assert.equal(r('finishDiceAnimation50(id)'),false);assert.equal(r('rollCalls'),1);r('settleDiceRoll50(id)');assert.equal(r('rollCalls'),1);
});
test('copied Growth Spurt rolls independently, retains its target and pays only once',()=>{
 const r=game(true);r(`ally();hand('Doublecast','Growth Spurt');playCard(0);globalThis.m=state.battle.mana;globalThis.values=[0,.99];Math.random=()=>values.shift();playCard(0);pick('player:a');globalThis.first=state.battle.diceRoll.id`);
 diceContinue50(r);assert.equal(r('state.battle.creatures[0].power'),3);assert.equal(r('state.battle.diceRoll.results[0]'),6);assert.equal(r('settleDiceRoll50(first)'),false);diceContinue50(r);
 assert.equal(r('state.battle.creatures[0].power'),9);assert.equal(r('state.battle.diceHistory.map(x=>x.results[0]).join()'),'1,6');assert.equal(r('state.battle.mana'),r('m-2'));assert.equal(r(`state.battle.graveyard.filter(c=>c.name==='Growth Spurt').length`),1);r('expireTurnEffects(state.battle)');assert.equal(r('state.battle.creatures[0].power'),2);
});
