 const r=counterGame44();r(`ally();hand('Growth Spurt');globalThis.calls=0;Math.random=()=>{calls++;return .5};playCard(0);pick('player:a')`);assert.equal(r('calls'),0);assert.equal(r('state.battle.diceRoll||null'),null);r('handleCombatAction()');assert.equal(r('calls'),0);assert.equal(r('state.battle.creatures[0].power'),2);assert.equal(r('state.battle.resolutionTask'),null);
