 const r=counterGame44();r(`ally();hand('Growth Spurt','Dispel');Math.random=()=>.5;playCard(0);pick('player:a');playCard(0);pick('spell:'+activeEnemySpell38().id)`);assert.equal(r('state.battle.diceRoll||null'),null);r('handleCombatAction()');assert.equal(r('state.battle.diceRoll.results[0]'),4);diceContinue50(r);assert.equal(r('state.battle.creatures[0].power'),6);
