function reactionGame52(){const r=game(true,true);r(`globalThis.b=state.battle;b.turn=2;globalThis.e=createFoe('archivist',3);e.health=e.maxHealth=50;e.ward=0;b.enemyCreatures=[e];b.waves=[b.enemyCreatures];b.waveIndex=0;`);return r;}
test('enemy Counterspell needs a visible four-plus roll before becoming a spell',()=>{
 for(const result of [1,2,3,4,5,6]){const r=reactionGame52();r(`hand('Divination');globalThis.n=b.deck.length;rollD6Value50=()=>${result};playCard(0)`);assert.equal(r('b.enemyCounterWindow||null'),null);assert.equal(r('b.enemyCastCheck.spellName'),'Counterspell');assert.equal(r('b.deck.length'),r('n'));diceContinue50(r);if(result>=4){assert.equal(r('b.enemyCounterWindow.spell.card.name'),'Counterspell');assert.equal(r('b.enemyCounterWindow.spell.manaPaid'),2);r('handleCombatAction()');assert.equal(r('b.hand.length'),0);}else{assert.equal(r('b.enemyCounterWindow||null'),null);assert.equal(r('b.hand.length'),2);assert.equal(r('b.enemyCounterFailedTurn'),2);assert.equal(r('b.enemySpells||null'),null);}assert.equal(r('b.enemyCastCheck'),null);}
});
test('failed Counterspell attempts are spent for the turn and cannot reroll on another spell',()=>{const r=reactionGame52();r(`hand('Divination','Divination');globalThis.rolls=0;rollD6Value50=()=>{rolls++;return 2};playCard(0)`);diceContinue50(r);r('playCard(0)');assert.equal(r('rolls'),1);assert.equal(r('b.diceRoll'),null);assert.equal(r('b.hand.length'),4);assert.equal(r('enemyCounterReady44(e)'),false);});
test('a successful enemy check still allows counter-counterspell and resumes original costs once',()=>{const r=reactionGame52();r(`hand('Grizzly Bears','Counterspell');globalThis.m=b.mana;rollD6Value50=()=>6;playCard(0,'player')`);diceContinue50(r);r(`playCard(0);pick('spell:'+activeEnemySpell38().id);handleCombatAction()`);assert.equal(r('b.creatures.length'),1);assert.equal(r('b.creatures[0].card.name'),'Grizzly Bears');assert.equal(r('b.mana'),r('m-4'));assert.equal(r('b.enemyCounterWindow'),null);});
test('each announced enemy spell rolls independently and only successful casts can resolve',()=>{
 const r=game(true,true);r(`globalThis.b=state.battle;b.phase='enemy';b.turn=2;b.hand=[];b.enemyCreatures=['archivist','duelist','vampire'].map((kind,i)=>{const e=createFoe(kind,3);e.pattern=[['rune','scorch','drain'][i]];return e});globalThis.life=state.playerHealth;globalThis.values=[2,4,1];rollD6Value50=()=>values.shift();resolveEnemyIntents();enemySpellWindow38(b,()=>{})`);
 assert.equal(r('b.enemySpells[0].status'),'awaiting-roll');assert.equal(r('state.playerHealth'),r('life'));diceContinue50(r);assert.equal(r('b.enemySpells[0].status'),'failed');assert.equal(r('b.diceRoll.results[0]'),4);diceContinue50(r);assert.equal(r('b.enemySpells[1].status'),'pending');r('resolveEnemySpell38(b.enemySpells[1]);enemySpellWindow38(b,()=>{})');assert.equal(r('state.playerHealth'),r('life-3'));diceContinue50(r);assert.equal(r('b.enemySpells[2].status'),'failed');assert.equal(r('b.enemySpellGraveyard.length'),1);
});
