test('spells already cast remain independent of their source after a successful check',()=>{const r=game(true,true);r(`globalThis.b=state.battle;b.phase='enemy';b.hand=[];b.enemyCreatures=[createFoe('duelist',3)];b.enemyCreatures[0].pattern=['scorch'];rollD6Value50=()=>4;globalThis.life=state.playerHealth;resolveEnemyIntents();enemySpellWindow38(b,()=>{})`);diceContinue50(r);r('b.enemyCreatures=[];resolveEnemySpell38(b.enemySpells[0])');assert.equal(r('state.playerHealth'),r('life-3'));});
test('Mill and ordinary attacks are abilities and do not require spell checks',()=>{const r=game(true,true);r(`globalThis.b=state.battle;b.phase='enemy';b.enemyCreatures=[createFoe('wisp',3)];b.enemyCreatures[0].pattern=['mill'];b.enemyCreatures[0].millAmount=2;globalThis.n=b.deck.length;resolveEnemyIntents()`);assert.equal(r('b.deck.length'),r('n-2'));assert.equal(r('pendingEnemySpells38().length'),0);assert.equal(r('b.diceRoll||null'),null);});
test('unaffordable Ward warns before any casting cost and cancel preserves the hand and sources',()=>{
 const r=game(true,true);r(`globalThis.b=state.battle;globalThis.e=b.enemyCreatures[0];e.ward=3;b.lands=[];b.floatingMana=2;syncMana(b);hand('Shock');playCard(0);pick('enemy:'+e.id)`);assert.notEqual(r('b.wardCastWarning'),null);assert.equal(r('b.hand[0].name'),'Shock');assert.equal(r('b.mana'),2);assert.equal(r('b.graveyard.length'),0);assert.equal(r('b.wardTask||null'),null);r('answerWardCasting52(false)');assert.equal(r('b.hand[0].name'),'Shock');assert.equal(r('b.floatingMana'),2);assert.equal(r('b.resolutionTask'),null);
});
