test('enough floating and untapped mana does not warn; exact Ward payment still works',()=>{const r=game(true,true);r(`globalThis.b=state.battle;globalThis.e=b.enemyCreatures[0];e.ward=2;b.lands=[];b.floatingMana=3;syncMana(b);hand('Shock');playCard(0);pick('enemy:'+e.id)`);assert.equal(r('b.wardCastWarning||null'),null);assert.notEqual(r('b.wardTask'),null);r('answerWard27(true)');assert.equal(r('b.mana'),0);assert.equal(r('e.health'),48);});
